  using result_type = decltype(std::declval<URNG&>()());
  template<typename... Args>
  auto operator()(URNG& g, Args&&... args) -> std::result_of_t<URNG&()> {
    return g(std::forward<Args>(args)...);
  }
};
int main() {
  std::mt19937 gen;
  std::uniform_int_distribution<> dist(1, 10);
  MyDistribution<std::mt19937> myDist;
  auto result = myDist(gen);
  std::cout << "Result: " << result << std::endl; // Compile-time determined type
  std::uniform_real_distribution<> realDist(0.0, 1.0);
  MyDistribution<std::uniform_real_distribution<>> myRealDist;
  auto realResult = myRealDist(realDist);
  std::cout << "Real Result: " << realResult << std::endl; // Different compile-time determined type
  return 0;
