    int val;  // Built-in type, which is movable
    // No user-defined move operations; compiler synthesizes them
};

int main() {
    X source{42};  // Create an object
    X destination = std::move(source);  // Compiler uses synthesized move constructor
    std::cout << "Moved value: " << destination.val << std::endl;  // Outputs: Moved value: 42
    return 0;
}
```

